INSERT INTO sync_logs (source,indicator_count,inserted_count,updated_count,failed_count,note) VALUES ('国家统计局 · 国家数据 API', 29, 1840, 0, 0, '第一批 12 序列 + 第二批 10 序列（GDP 实际同比、核心 CPI、PPI、年末总人口、一般公共预算收入、出口同比、社零、规上工业、固投、房地产投资）+ 第三批货物进出口 7 序列（进出口/出口/进口/差额当月值、进出口与进口同比、进出口累计同比）；进出口目录原始单位为千美元，金额类统一除以 100000 换算为亿美元，同比类不换算；指数类由上年同月/上年同期=100 换算为同比；CPI 按 5 年分片逐段拼接，核心 CPI 仅 2021 年起提供；季度 dts 不可用，GDP 实际同比按年度粒度落库；空值不入图、不插值；转载须注明转自国家统计局网站 www.stats.gov.cn')